if (Object.keys(row).length !== keys.length || keys.some(key => !Object.hasOwn(row, key))) throw new Error('Graph record members differ from its schema');
for (const item of Object.values(row)) if (typeof item === 'string') for (const scalar of item) { const point = scalar.codePointAt(0)!; if (point >= 0xd800 && point <= 0xdfff) throw new Error('Graph text requires Unicode scalar values'); }
return row;
